<div class="page-actions"><a class="back-link" href="<?= site_url('admin/modul/pengawasan') ?>">← Daftar pemeriksaan</a><a class="button button-quiet" href="<?= site_url('admin/pengawasan/'.$row['id'].'/berita-acara') ?>" target="_blank" rel="noopener">Berita acara draf ↗</a><?php if ($can_edit && $row['status']==='planned'): ?><a class="button button-dark" href="<?= site_url('admin/pengawasan/'.$row['id'].'/ubah') ?>">Ubah rencana</a><?php endif; ?></div>
<?php if ($can_finish && $row['status']!=='completed'): ?><form class="inspection-finish" method="post" action="<?= site_url('admin/pengawasan/'.$row['id'].'/selesai') ?>"><?= csrf_input() ?><span><?= $open_count ? $open_count.' temuan masih terbuka.' : 'Semua temuan sudah ditutup.' ?></span><button class="button button-dark button-small" <?= $open_count || !$row['assignment_number'] || !$row['lead_user_id'] || !$row['started_on']?'disabled':'' ?>>Tandai pemeriksaan selesai</button></form><?php endif; ?><div class="profile-head"><div><span class="panel-overline"><?= h($row['assignment_number']?:'Nomor tugas belum diisi') ?></span><h2><?= h($row['cooperative_name']) ?></h2><p><?= h($row['nik']?:'NIK belum tersedia') ?> · <?= $row['inspection_type']==='routine'?'Pemeriksaan rutin':'Pemeriksaan insidental' ?></p></div><span class="pill pill-blue"><?= h($statuses[$row['status']]??$row['status']) ?></span></div>
<div class="detail-grid"><section class="panel detail-panel"><span class="panel-overline">PENUGASAN</span><dl><dt>Petugas</dt><dd><?= h($row['lead_name']?:'Belum ditugaskan') ?></dd><dt>Tanggal mulai</dt><dd><?= $row['started_on']?h(date('d M Y',strtotime($row['started_on']))):'Belum ditetapkan' ?></dd><dt>Tanggal selesai</dt><dd><?= $row['ended_on']?h(date('d M Y',strtotime($row['ended_on']))):'—' ?></dd></dl></section><section class="panel detail-panel"><span class="panel-overline">DATA TERKAIT</span><dl><dt>Penilaian</dt><dd><?php if ($row['assessment_id']): ?><a href="<?= site_url('admin/penilaian/'.$row['assessment_id']) ?>">Penilaian tahun buku <?= h($row['assessment_year']) ?> ↗</a><?php else: ?>Belum ditautkan<?php endif; ?></dd><dt>Jumlah temuan</dt><dd><?= count($findings) ?></dd></dl></section></div>
<?php if ($row['assessment_id']): ?><section class="panel detail-panel"><span class="panel-overline">JAWABAN MANDIRI TERKAIT</span><p>Indikator berikut dijawab “Tidak Terpenuhi” oleh koperasi. Petugas tetap perlu memeriksa fakta sebelum mencatat temuan.</p><?php foreach ($unmet as $u): ?><div class="evidence-row"><strong>Input #<?= h($u['indicator_code']) ?></strong><span><?= h($u['prompt']) ?></span></div><?php endforeach; ?><?php if (!$unmet): ?><p class="empty-cell">Tidak ada jawaban “Tidak Terpenuhi” pada penilaian terkait.</p><?php endif; ?></section><?php endif; ?>
<?php if (($can_create || $can_edit) && $row['status']!=='completed'): ?><section class="form-panel"><div class="form-intro"><span class="panel-overline">TEMUAN BARU</span><h2>Catat fakta lapangan</h2><p>Dasar hukum, rekomendasi, dan tanggapan koperasi akan masuk ke berita acara draf.</p></div><form id="finding-form" method="post" action="<?= site_url('admin/pengawasan/'.$row['id'].'/temuan') ?>"><?= csrf_input() ?><input type="hidden" name="finding_id" value=""><div class="form-grid"><label>Kode indikator KKPKK terkait<input name="indicator_code" maxlength="80" placeholder="Opsional, contoh: 42"></label><label>Aspek <span class="required">*</span><input name="aspect_code" maxlength="80" required placeholder="Contoh: Tata kelola"></label><label>Batas tindak lanjut<input type="date" name="due_on"></label><label class="form-full">Fakta <span class="required">*</span><textarea name="fact" rows="3" minlength="10" required></textarea></label><label class="form-full">Dasar hukum<input name="legal_basis" placeholder="Pasal atau ketentuan terkait"></label><label class="form-full">Rekomendasi<textarea name="recommendation" rows="2"></textarea></label><label class="form-full">Tanggapan koperasi<textarea name="cooperative_response" rows="2"></textarea></label></div><div class="form-actions"><button class="button button-dark">Simpan temuan →</button></div></form></section><?php endif; ?>
<section class="panel detail-panel"><span class="panel-overline">DAFTAR TEMUAN</span><?php foreach ($findings as $f): ?><article class="inspection-finding"><div class="inspection-finding-head"><strong><?= h($f['aspect_code']) ?><?= $f['indicator_code']?' · Input #'.h($f['indicator_code']):'' ?></strong><span class="pill <?= $f['status']==='closed'?'pill-green':'pill-blue' ?>"><?= $f['status']==='closed'?'Ditutup':'Terbuka' ?></span><?php if ($can_edit && $row['status']!=='completed' && $f['status']!=='closed'): ?><button class="text-button finding-edit" type="button" data-id="<?= $f['id'] ?>" data-indicator="<?= h($f['indicator_code']) ?>" data-aspect="<?= h($f['aspect_code']) ?>" data-fact="<?= h($f['fact']) ?>" data-legal="<?= h($f['legal_basis']) ?>" data-recommendation="<?= h($f['recommendation']) ?>" data-response="<?= h($f['cooperative_response']) ?>" data-due="<?= h($f['due_on']) ?>">Ubah</button><?php endif; ?><?php if ($can_archive && $row['status']!=='completed' && $f['status']!=='closed' && empty($actions[$f['id']])): ?><form method="post" action="<?= site_url('admin/pengawasan/'.$row['id'].'/temuan/'.$f['id'].'/hapus') ?>" onsubmit="return confirm('Hapus temuan ini?')"><?= csrf_input() ?><button class="text-button" type="submit">Hapus</button></form><?php endif; ?></div><p><?= nl2br(h($f['fact'])) ?></p><?php if ($f['recommendation']): ?><small><strong>Rekomendasi:</strong> <?= h($f['recommendation']) ?></small><?php endif; ?><?php if ($f['due_on']): ?><small>Target: <?= h(date('d M Y',strtotime($f['due_on']))) ?></small><?php endif; ?><div class="case-timeline"><?php foreach (($actions[$f['id']]??array()) as $a): ?><div class="timeline-item"><strong><?= h($a['owner_name']?:'Petugas') ?> · <?= h(date('d M Y H:i',strtotime($a['created_at']))) ?></strong><p><?= nl2br(h($a['action_text'])) ?></p><small>Status: <?= h($a['status']) ?></small></div><?php endforeach; ?></div><?php if ($can_edit && $row['status']!=='completed'): ?><form class="inspection-action" method="post" action="<?= site_url('admin/pengawasan/'.$row['id'].'/temuan/'.$f['id'].'/tindaklanjut') ?>"><?= csrf_input() ?><label>Catatan tindak lanjut<textarea name="action_text" rows="2" minlength="5" required></textarea></label><label>Status<select name="status"><option value="open">Terbuka</option><option value="submitted">Disampaikan</option><option value="verified">Terverifikasi</option></select></label><button class="button button-dark button-small">Simpan</button></form><?php endif; ?></article><?php endforeach; ?><?php if (!$findings): ?><p class="empty-cell">Belum ada temuan.</p><?php endif; ?></section>
<script>(function(){const form=document.getElementById('finding-form');if(!form)return;for(const button of document.querySelectorAll('.finding-edit'))button.addEventListener('click',()=>{for(const [name,value] of Object.entries({finding_id:button.dataset.id,indicator_code:button.dataset.indicator,aspect_code:button.dataset.aspect,fact:button.dataset.fact,legal_basis:button.dataset.legal,recommendation:button.dataset.recommendation,cooperative_response:button.dataset.response,due_on:button.dataset.due})){const field=form.elements.namedItem(name);if(field)field.value=value||'';}form.querySelector('button[type=submit]').disabled=false;form.scrollIntoView({behavior:'smooth',block:'center'});});})()</script>